{"content":"<#
.SYNOPSIS
    Minimal structured file logger shared by all RAZOR Service Manager modules.
#>

$script:LogPath = "$PSScriptRoot/../svcmgr.log"

function Write-Log {
    param(
        [ValidateSet("INFO","WARN","ERROR","DEBUG")][string]$Level = "INFO",
        [Parameter(Mandatory)][string]$Message
    )
    $line = "{0} [{1}] {2}" -f (Get-Date -Format "s"), $Level, $Message
    Add-Content -Path $script:LogPath -Value $line -Encoding UTF8
    if ($Level -in @("ERROR","WARN")) { Write-Host $line }
}

function Get-RecentLogs {
    param([int]$Count = 50)
    if (-not (Test-Path $script:LogPath)) { return @() }
    return Get-Content $script:LogPath -Tail $Count
}

Export-ModuleMember -Function Write-Log, Get-RecentLogs
